ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *Parent;
    ACPI_PARSE_OBJECT *Next;

    /* Validate input parameters */
    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    /* Check if the operation has a parent */
    Parent = Op->Common.Parent;
    if (!Parent) {
        return (AE_NULL_POINTER);
    }

    /* Call the ascending callback if it exists */
    if (WalkState->DescendingCallback && WalkState->AscendingCallback) {
        Status = WalkState->AscendingCallback(WalkState, Op, Status);
        if (ACPI_FAILURE(Status)) {
            return (Status);
        }
    }

    /* Get the next operation in the stack */
    Next = Op->Common.Next;

    /* Process the next operation if it exists */
    if (Next) {
        return (AcpiPsCompleteFinalOp(WalkState, Next, Status));
    }

    /* If no more operations in the stack, clear the scope */
    WalkState->Scope->ParseOp = NULL;

    /* Return the final status */
    return (Status);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_PARSE_OBJECT *PrevOp;
    ACPI_PARSE_OBJECT *NextOp;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    PrevOp = Op->Common.Next;
    while (PrevOp != Op) {
        NextOp = PrevOp->Common.Next;

        if (PrevOp->ParseOpcode == A_OP_SCOPE) {
            if (PrevOp->Value.String) {
                ACPI_FREE(PrevOp->Value.String);
            }
        }

        if (PrevOp->Common.Value.Displacement) {
            ACPI_FREE(PrevOp->Common.Value.Displacement);
        }

        ACPI_FREE(PrevOp);
        PrevOp = NextOp;
    }

    if (WalkState->Control.Method) {
        if (WalkState->Control.Method->ParseTree) {
            AcpiUtReleaseMutex(WalkState->Control.Method->Mutex);
        }
    }

    if (Status != AE_CTRL_TRANSFERRED) {
        if (WalkState->Control.Method) {
            WalkState->Control.Method->ArgCount = WalkState->Control.Arguments;
        }
    }

    if (Status == AE_CTRL_CONTINUE || Status == AE_CTRL_TRANSFERRED) {
        return (AE_OK);
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *ParentOp;

    if (!WalkState || !Op)
    {
        return (AE_BAD_PARAMETER);
    }

    if (WalkState->Op == Op)
    {
        WalkState->Op = Op->Common.Next;
    }

    if (WalkState->Control.ImmediateChildren)
    {
        Op->Common.Value.Arg = WalkState->Control.ImmediateChildren;
        WalkState->Control.ImmediateChildren = NULL;
    }

    if (WalkState->Control.ParentOp == Op)
    {
        WalkState->Control.ParentOp = NULL;
    }

    ParentOp = Op->Common.Parent;
    if (ParentOp && ParentOp != Op)
    {
        if (ParentOp->Common.Value.Arg)
        {
            ACPI_PARSE_OBJECT *ArgList = ParentOp->Common.Value.Arg;

            while (ArgList->Next)
            {
                ArgList = ArgList->Next;
            }

            ArgList->Next = Op;
        }
        else
        {
            ParentOp->Common.Value.Arg = Op;
        }
    }

    if (WalkState->MethodsToClose)
    {
        AcpiUtReleaseMutex(WalkState->Mutex);
        WalkState->Mutex = NULL;
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteScope(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *PrevOp;

    do {
        if (!Op) {
            return (AE_CTRL_EXIT);
        }

        if (Op->Common.Value.ArgList) {
            AcpiUtReleaseObjectList(Op->Common.Value.ArgList);
        }

        PrevOp = Op->Common.Parent;
        if (WalkState->ParserState.NextOp == Op) {
            WalkState->ParserState.NextOp = PrevOp;
        }

        if (Op->Common.DescType == ACPI_DESC_TYPE_PARSER) {
            if (Op->Common.Value.ObjHandle) {
                AcpiUtReleaseObjectDesc(Op->Common.Value.ObjHandle);
            }

            if (Op->Named.NextName) {
                AcpiUtReleaseObjectDesc(Op->Named.NextName);
            }
        }

        Op = PrevOp;

        if (WalkState->Control.MethodCount) {
            WalkState->Control.MethodCount--;
        }

        if (WalkState->Control.ParamCount) {
            WalkState->Control.ParamCount--;
        }

        if (WalkState->ParserState.Scope->List) {
            WalkState->ParserState.Scope->List = Op;
        }

        if (WalkState->ParserState.Scope->NumNodes) {
            WalkState->ParserState.Scope->NumNodes--;
        }

        if (WalkState->Control.State == ACPI_IMODE_EXECUTE) {
            Status = AcpiPsCallCompletedOp(WalkState, Op, Status);
            if (Status == AE_CTRL_TRANSFER || Status == AE_CTRL_EXIT) {
                return (Status);
            }
        }

    } while (Op && (Op->Common.Parent || (WalkState->ParserState.Scope->List == Op)));

    return (Status);
}

ACPI_STATUS AcpiPsCompleteOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *PrevOp;

    if (!WalkState || !WalkState->ParserState.Scope.Obj || !WalkState->ParserState.Scope.Obj->Common.Value)
    {
        return (AE_BAD_PARAMETER);
    }

    if (!Op)
    {
        return (AE_BAD_PARAMETER);
    }

    if (WalkState->DescendingCallback)
    {
        Status = WalkState->DescendingCallback(WalkState, Op, &Status);
        if (ACPI_FAILURE(Status))
        {
            return (Status);
        }
    }

    PrevOp = WalkState->ParserState.Scope.Obj;
    if (PrevOp && PrevOp->Common.Value && PrevOp->Common.Value->Name.Aml)
    {
        if (WalkState->AscendingCallback)
        {
            Status = WalkState->AscendingCallback(WalkState, Op, &Status);
            if (ACPI_FAILURE(Status))
            {
                return (Status);
            }
        }

        if (WalkState->WalkNumber == WalkState->ParserState.Scope.WalkNum)
        {
            WalkState->ParserState.Scope.Obj = PrevOp;
            if (WalkState->ParserState.Scope.Obj->ParseOpList)
            {
                WalkState->ParserState.Scope.Obj->ParseOpList->Tail = Op;
            }
        }
    }

    return (Status);
}
